"use client";

import { CHAPTERS } from "@/lib/chapters";
import type {
  ExamPrepTrack,
  FoundationTrack,
  GenerateFilters,
  Grade,
  PreparationLevel,
  QuestionType,
} from "@/lib/types";
import { useState } from "react";

interface FilterPanelProps {
  onGenerate: (filters: GenerateFilters) => void;
  loading: boolean;
}

const ALL_TYPES: QuestionType[] = ["MCQ", "NAT", "FITB"];

const FOUNDATION_TRACKS: { value: FoundationTrack; label: string }[] = [
  { value: "CONCEPTUAL_QUIZ", label: "Conceptual Quiz" },
  { value: "CALCULATION_APPLICATION", label: "Calculation Application" },
  { value: "FUTURE_TECH_LAB", label: "Future Tech Applications" },
];

const EXAM_PREP_TRACKS: { value: ExamPrepTrack; label: string }[] = [
  { value: "TOPIC_DRILL", label: "Topic Drills" },
  { value: "FULL_PATTERN_MOCK", label: "Full Mock Tests" },
];

export default function FilterPanel({
  onGenerate,
  loading,
}: FilterPanelProps) {
  const [grade, setGrade] = useState<Grade>("11");
  const [chapter, setChapter] = useState<GenerateFilters["chapter"]>(
    "units-and-measurements",
  );
  const [difficulty, setDifficulty] =
    useState<GenerateFilters["difficulty"]>("Mixed");
  const [count, setCount] = useState(8);
  const [types, setTypes] = useState<QuestionType[]>([...ALL_TYPES]);
  const [includeAnswerKey, setIncludeAnswerKey] = useState(true);
  const [preparationLevel, setPreparationLevel] =
    useState<PreparationLevel>("FOUNDATION");
  const [foundationTracks, setFoundationTracks] = useState<FoundationTrack[]>([
    "CONCEPTUAL_QUIZ",
  ]);
  const [examPrepTracks, setExamPrepTracks] = useState<ExamPrepTrack[]>([
    "TOPIC_DRILL",
  ]);

  function toggleType(t: QuestionType) {
    setTypes((prev) =>
      prev.includes(t) ? prev.filter((x) => x !== t) : [...prev, t],
    );
  }

  function toggleFoundationTrack(t: FoundationTrack) {
    setFoundationTracks((prev) =>
      prev.includes(t) ? prev.filter((x) => x !== t) : [...prev, t],
    );
  }

  function toggleExamPrepTrack(t: ExamPrepTrack) {
    setExamPrepTracks((prev) =>
      prev.includes(t) ? prev.filter((x) => x !== t) : [...prev, t],
    );
  }

  return (
    <form
      className="no-print space-y-5 rounded-xl border border-zinc-200 bg-white p-5 shadow-sm"
      onSubmit={(e) => {
        e.preventDefault();
        onGenerate({
          subject: "Physics",
          grade,
          chapter,
          difficulty,
          types: types.length ? types : ALL_TYPES,
          count,
          includeAnswerKey,
          preparationLevel,
          trackTypes:
            preparationLevel === "FOUNDATION" ? foundationTracks : examPrepTracks,
        });
      }}
    >
      <div>
        <p className="text-xs font-medium uppercase tracking-wide text-zinc-500">
          Class {grade} · Physics · NCERT
        </p>
        <h2 className="mt-1 text-lg font-semibold text-zinc-900">
          Generate worksheet
        </h2>
      </div>

      <fieldset>
        <legend className="text-sm font-medium text-zinc-700">
          Preparation level
        </legend>
        <div className="mt-2 flex overflow-hidden rounded-lg border border-zinc-300">
          <button
            type="button"
            onClick={() => setPreparationLevel("FOUNDATION")}
            className={`flex-1 px-3 py-2 text-xs font-medium transition ${
              preparationLevel === "FOUNDATION"
                ? "bg-zinc-900 text-white"
                : "bg-white text-zinc-600 hover:bg-zinc-50"
            }`}
          >
            Foundation Track
          </button>
          <button
            type="button"
            onClick={() => setPreparationLevel("JEE_EXAM_PREP")}
            className={`flex-1 border-l border-zinc-300 px-3 py-2 text-xs font-medium transition ${
              preparationLevel === "JEE_EXAM_PREP"
                ? "bg-zinc-900 text-white"
                : "bg-white text-zinc-600 hover:bg-zinc-50"
            }`}
          >
            JEE Exam Prep
          </button>
        </div>
      </fieldset>

      {preparationLevel === "FOUNDATION" ? (
        <fieldset>
          <legend className="text-sm font-medium text-zinc-700">
            Foundation tracks
          </legend>
          <div className="mt-2 flex flex-wrap gap-2">
            {FOUNDATION_TRACKS.map((track) => (
              <label
                key={track.value}
                className={`cursor-pointer rounded-full border px-3 py-1 text-xs font-medium ${
                  foundationTracks.includes(track.value)
                    ? "border-zinc-900 bg-zinc-900 text-white"
                    : "border-zinc-300 text-zinc-600"
                }`}
              >
                <input
                  type="checkbox"
                  className="sr-only"
                  checked={foundationTracks.includes(track.value)}
                  onChange={() => toggleFoundationTrack(track.value)}
                />
                {track.label}
              </label>
            ))}
          </div>
        </fieldset>
      ) : (
        <fieldset>
          <legend className="text-sm font-medium text-zinc-700">
            Exam prep tracks
          </legend>
          <div className="mt-2 flex flex-wrap gap-2">
            {EXAM_PREP_TRACKS.map((track) => (
              <label
                key={track.value}
                className={`cursor-pointer rounded-full border px-3 py-1 text-xs font-medium ${
                  examPrepTracks.includes(track.value)
                    ? "border-zinc-900 bg-zinc-900 text-white"
                    : "border-zinc-300 text-zinc-600"
                }`}
              >
                <input
                  type="checkbox"
                  className="sr-only"
                  checked={examPrepTracks.includes(track.value)}
                  onChange={() => toggleExamPrepTrack(track.value)}
                />
                {track.label}
              </label>
            ))}
          </div>
        </fieldset>
      )}

      <label className="block text-sm font-medium text-zinc-700">
        Grade target
        <select
          className="mt-1 w-full rounded-lg border border-zinc-300 bg-white px-3 py-2 text-sm"
          value={grade}
          onChange={(e) => {
            const nextGrade = e.target.value as Grade;
            setGrade(nextGrade);
            setChapter(
              nextGrade === "12" ? "p12_01" : "units-and-measurements",
            );
          }}
        >
          <option value="11">Class 11</option>
          <option value="12">Class 12</option>
        </select>
      </label>


      <label className="block text-sm font-medium text-zinc-700">
        Chapter
        <select
          className="mt-1 w-full rounded-lg border border-zinc-300 bg-white px-3 py-2 text-sm"
          value={chapter}
          onChange={(e) =>
            setChapter(e.target.value as GenerateFilters["chapter"])
          }
        >
          {CHAPTERS.filter((c) =>
            grade === "12" ? c.id.startsWith("p12_") : !c.id.startsWith("p12_"),
          ).map((c) => (
            <option key={c.id} value={c.id}>
              {c.title}
            </option>
          ))}
        </select>
      </label>

      <label className="block text-sm font-medium text-zinc-700">
        Difficulty
        <select
          className="mt-1 w-full rounded-lg border border-zinc-300 bg-white px-3 py-2 text-sm"
          value={difficulty}
          onChange={(e) =>
            setDifficulty(e.target.value as GenerateFilters["difficulty"])
          }
        >
          <option>Mixed</option>
          <option>Easy</option>
          <option>Medium</option>
          <option>Hard</option>
        </select>
      </label>

      <fieldset>
        <legend className="text-sm font-medium text-zinc-700">
          Question types
        </legend>
        <div className="mt-2 flex flex-wrap gap-2">
          {ALL_TYPES.map((t) => (
            <label
              key={t}
              className={`cursor-pointer rounded-full border px-3 py-1 text-xs font-medium ${
                types.includes(t)
                  ? "border-zinc-900 bg-zinc-900 text-white"
                  : "border-zinc-300 text-zinc-600"
              }`}
            >
              <input
                type="checkbox"
                className="sr-only"
                checked={types.includes(t)}
                onChange={() => toggleType(t)}
              />
              {t === "MCQ"
                ? "Multiple choice"
                : t === "NAT"
                  ? "Numerical"
                  : "Fill in the blank"}
            </label>
          ))}
        </div>
      </fieldset>

      <label className="block text-sm font-medium text-zinc-700">
        Number of questions
        <input
          type="number"
          min={1}
          max={20}
          className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2 text-sm"
          value={count}
          onChange={(e) => setCount(Number(e.target.value))}
        />
      </label>

      <label className="flex items-center gap-2 text-sm text-zinc-700">
        <input
          type="checkbox"
          checked={includeAnswerKey}
          onChange={(e) => setIncludeAnswerKey(e.target.checked)}
        />
        Include answer key
      </label>

      <button
        type="submit"
        disabled={loading}
        className="w-full rounded-lg bg-zinc-900 px-4 py-2.5 text-sm font-medium text-white hover:bg-zinc-800 disabled:opacity-60"
      >
        {loading ? "Generating…" : "Generate worksheet"}
      </button>
    </form>
  );
}
